const NL = String.fromCharCode(10);
const job = $('When called by parent').first().json;
const iso = job.iso;
const pages = $input.all();
const errors = [];
let keys = [];
for (const p of pages) {
  const j = p.json || {};
  const body = j.body !== undefined ? j.body : j;
  if (body && Array.isArray(body.keys)) { keys = keys.concat(body.keys); }
  else { errors.push('Lokalise page without keys array: ' + JSON.stringify(body).slice(0, 200)); }
}

const UB = '(?:(?<![\\p{L}\\p{N}_])(?=[\\p{L}\\p{N}_])|(?<=[\\p{L}\\p{N}_])(?![\\p{L}\\p{N}_]))';
function rx(src, flags) { return new RegExp(String(src).split('\\b').join(UB), 'u' + (flags || '')); }
const MARKUP = /\[%[^\]]*\]|%\d*\$?[sdfx@]|\{\{[^}]*\}\}|%\{[^}]*\}|\{[^}\s]*\}|<[^>]+>|&[a-zA-Z#0-9]+;|https?:\/\/\S+|[\w.+-]+@[\w-]+\.[\w.]+|\\[nrt]/g;
function strip(s) { return String(s || '').replace(MARKUP, ' '); }
function pickText(tr) {
  if (tr === null || tr === undefined) { return ''; }
  if (typeof tr === 'object') { return Object.values(tr).filter(function (v) { return v; }).join(' ¦ '); }
  const s = String(tr);
  if (s.charAt(0) === '{' && s.indexOf('"') !== -1) {
    try { const o = JSON.parse(s); if (o && typeof o === 'object') { return Object.values(o).filter(function (v) { return v; }).join(' ¦ '); } } catch (e) { }
  }
  return s;
}

const rows = [];
const META = {};
let archived = 0;
for (const k of keys) {
  if (k.is_archived) { archived++; continue; }
  const kn = k.key_name || {};
  const name = typeof kn === 'string' ? kn : (kn.web || kn.other || kn.ios || kn.android || String(k.key_id));
  let en = '';
  let tgt = '';
  for (const t of (k.translations || [])) {
    if (t.language_iso === 'en') { en = pickText(t.translation); }
    if (t.language_iso === iso) { tgt = pickText(t.translation); }
  }
  if (!en.trim() || !tgt.trim()) { continue; }
  const tags = Array.isArray(k.tags) ? k.tags.map(String) : [];
  META[name] = { d: String(k.description || k.context || '').trim().slice(0, 300), tags: tags.slice(0, 8) };
  rows.push({ k: name, en: en, t: tgt });
}

// ---------- glossary ----------
const WORD = /[\p{L}\p{M}]+(?:['’\-][\p{L}\p{M}]+)*/gu;
function norm(s) { return String(s).normalize('NFC').replace(/[\u00A0\u202F\u2009]/g, ' ').toLowerCase(); }
function words(s) { return (String(s).match(WORD) || []).map(norm); }
function variants(target) {
  const out = [];
  let rest = String(target);
  const pr = /[（(]([^)）]*)[)）]/g;
  let m;
  while ((m = pr.exec(target)) !== null) { if (m[1].trim()) { out.push(m[1].trim()); } }
  rest = rest.replace(pr, ' ');
  for (const part of rest.split(/\s*\/\s*|\s+or\s+|\s*\|\s*/)) { if (part.trim()) { out.push(part.trim()); } }
  return out.length ? out : [target];
}
function looseContains(text, phrase, ratio) {
  const r = ratio || 0.7;
  const toks = words(text);
  if (!toks.length) { return false; }
  let ws = words(phrase);
  const longw = ws.filter(function (w) { return w.length >= 3; });
  if (longw.length) { ws = longw; }
  if (!ws.length) { return norm(text).indexOf(norm(phrase)) !== -1; }
  for (const w of ws) {
    const need = w.length <= 4 ? w : w.slice(0, Math.max(4, Math.floor(w.length * r)));
    const ok = toks.some(function (t) { return t.indexOf(need) === 0 || (w.indexOf(t.slice(0, need.length)) === 0 && t.length >= need.length); });
    if (!ok) { return false; }
  }
  return true;
}
function esc(s) { return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
const gl = (job.glossary || []).slice().sort(function (a, b) { return b.src.length - a.src.length; });
for (const t of gl) {
  t.srx = new RegExp('(?<![\\p{L}\\p{N}])' + esc(t.src) + '(?![\\p{L}\\p{N}])', 'u' + (t.cs ? '' : 'i'));
}
// Thai has no spaces: prefix matching on words is meaningless, use substring.
const NOSPACE = iso === 'th';

const cands = [];
const hits = {};
const CAP_RULE = 25;
const CAP_TERM = 5;
function add(c) {
  const hk = c.type + ':' + c.rule;
  hits[hk] = (hits[hk] || 0) + 1;
  const cap = c.type === 'style' ? CAP_RULE : CAP_TERM;
  if (hits[hk] > cap) { return; }
  cands.push(c);
}

for (const r of rows) {
  const enS = strip(r.en);
  if (!enS.trim()) { continue; }
  const consumed = [];
  for (const t of gl) {
    if (!t.srx.test(enS)) { continue; }
    const low = t.src.toLowerCase();
    if (consumed.some(function (c) { return c.indexOf(low) !== -1; })) { continue; }
    consumed.push(low);
    if (!t.tr) {
      if (r.t.indexOf(t.src) === -1) {
        add({ type: 'glossary', sub: 'brand_not_preserved', rule: t.src, expected: t.src, sev: 'High', conf: 'high', key: r.k, en: r.en, target: r.t, note: t.note });
      }
      continue;
    }
    if (!t.tgt) { continue; }
    const vs = variants(t.tgt);
    const found = vs.some(function (v) { return NOSPACE ? norm(r.t).indexOf(norm(v)) !== -1 : looseContains(r.t, v); });
    if (found) { continue; }
    const cov = t.src.length / Math.max(enS.trim().length, 1);
    add({ type: 'glossary', sub: 'term_missing', rule: t.src, expected: t.tgt, sev: 'Medium', conf: cov > 0.6 ? 'high' : (cov > 0.25 ? 'medium' : 'low'), key: r.k, en: r.en, target: r.t, note: t.note });
  }
  for (const t of gl) {
    if (!t.fb) { continue; }
    const bad = t.tgt || t.src;
    const f = NOSPACE ? norm(r.t).indexOf(norm(bad)) !== -1 : looseContains(r.t, bad, 0.9);
    if (f) { add({ type: 'glossary', sub: 'forbidden_used', rule: t.src, expected: '', sev: 'High', conf: 'high', key: r.k, en: r.en, target: r.t, note: t.note }); }
  }
}

// ---------- style ----------
const rules = [];
for (const r of (job.rules || [])) {
  try {
    rules.push({ r: r, f: rx(r.forbid, r.flags), w: r.when_source ? new RegExp(r.when_source, 'iu') : null });
  } catch (e) { errors.push('bad regex in rule ' + r.id + ': ' + e.message); }
}
for (const row of rows) {
  const tS = strip(row.t);
  const enS = strip(row.en).trim();
  for (const x of rules) {
    if (x.w && !x.w.test(enS)) { continue; }
    const m = x.f.exec(x.r.raw ? row.t : tS);
    if (!m) { continue; }
    add({ type: 'style', sub: x.r.id, rule: x.r.id, expected: x.r.suggest || '', sev: x.r.sev, conf: 'rule', key: row.k, en: row.en, target: row.t, note: x.r.desc, match: m[0] });
  }
}

// ---------- prioritise for triage ----------
function prio(c) {
  if (c.sub === 'brand_not_preserved' || c.sub === 'forbidden_used') { return 0; }
  if (c.type === 'style' && c.sev === 'High') { return 1; }
  if (c.sub === 'term_missing' && c.conf === 'high') { return 2; }
  if (c.type === 'style' && c.sev === 'Medium') { return 3; }
  if (c.sub === 'term_missing' && c.conf === 'medium') { return 4; }
  if (c.type === 'style') { return 5; }
  return 6;
}
cands.sort(function (a, b) { return prio(a) - prio(b); });
const MAX_SEND = 160;
const send = cands.slice(0, MAX_SEND);
const overflow = cands.length - send.length;
function cut(s, n) { s = String(s || ''); return s.length > n ? s.slice(0, n) + '…' : s; }
const candPayload = send.map(function (c, i) {
  c.id = 'c' + (i + 1);
  const mt = META[c.key] || {};
  return { id: c.id, key: c.key, key_description: mt.d || undefined, key_tags: mt.tags && mt.tags.length ? mt.tags : undefined, check: c.type, kind: c.sub, rule_or_term: c.rule, expected: c.expected, rule_text: c.type === 'style' ? c.note : undefined, glossary_note: c.type === 'glossary' ? cut(c.note, 200) : undefined, matched: c.match, confidence: c.conf, en: cut(c.en, 500), target: cut(c.target, 500) };
});

const candKeys = {};
for (const c of send) { candKeys[c.key] = true; }
const seenT = {};
const sample = rows.filter(function (r) { return r.t.length >= 40 && !candKeys[r.k]; })
  .sort(function (a, b) { return b.t.length - a.t.length; })
  .filter(function (r) { const s = r.t.slice(0, 80); if (seenT[s]) { return false; } seenT[s] = true; return true; })
  .slice(0, 20)
  .map(function (r, i) { const mt = META[r.k] || {}; return { sid: 's' + (i + 1), key: r.k, key_description: mt.d || undefined, key_tags: mt.tags && mt.tags.length ? mt.tags : undefined, en: cut(r.en, 700), target: cut(r.t, 700) }; });

const systemic = {};
for (const hk in hits) {
  const cap = hk.indexOf('style:') === 0 ? CAP_RULE : CAP_TERM;
  if (hits[hk] > cap) { systemic[hk] = hits[hk]; }
}

const SYS = [
  'You are a senior ' + job.lang_name + ' (' + iso + ') localization reviewer auditing shipped UI and email strings of the product "' + job.project_name + '".',
  'Automatic checks flagged CANDIDATES against the team glossary and the ' + job.lang_name + ' style guide. Most candidates are false positives. Your job is triage: keep only what a native ' + job.lang_name + ' reviewer would call a real defect against the stated rule or glossary term. DEFAULT IS DROP; if unsure, drop.',
  'Glossary term_missing: drop when the translation uses the approved term with different inflection, compounding or word order, when the English term is used in a different sense, or when the approved term does not fit the sentence and the translator worked around it sensibly. Keep only when a genuinely different word was chosen. Read glossary_note: it often allows variants.',
  'brand_not_preserved / forbidden_used: near-certain; keep unless the target clearly contains the brand in another legitimate form (e.g. inside a URL or placeholder) or the English uses the word generically, not as the brand.',
  'Style candidates: the regex hit is only a hint; check the actual string (e.g. a capitalised pronoun that starts a sentence or refers to a third party is not a formality error). If a style hit is caused by a glossary-mandated term, drop it and say so in glossary_conflicts.',
  'Also review the SAMPLE strings against these ' + job.lang_name + ' style-guide rules and report only clear breaches: ' + (job.judgement || 'none') + (job.is_personality ? ' This is a Personality product.' : ''),
  'Every candidate and sample item carries its Lokalise key name, key_description and key_tags. Key-name segments are namespaces (e.g. emails.welcome.subject, checkout.buttons.pay, legal.terms.section_3, test.questions.q12) that tell you where and how the string is used. Whenever you are unsure whether a string is a button, label, heading, sentence, email, legal text, test item or a third-party/brand reference, read the key name, description and tags before deciding, and let that context settle label-vs-sentence rules, formality, brand usage and whether a glossary term applies in that sense.',
  'Judge each candidate ONLY against its own rule_or_term. Never use a candidate to report a different problem (another rule, formality, another term) — other problems have their own candidates. Glossary terms are often context-specific: if the English uses the word in another sense (verb vs noun, generic word vs UI label) or the approved target clearly belongs to a different context, drop it. A faithful rephrase with the same meaning is not a defect.',
  'For every kept candidate also give "certainty": "high" only if a native reviewer would certainly ask for a change; otherwise "low" (low items are discarded).',
  'sample_findings must contain ONLY clear breaches that need a change. Never list strings that are fine, acceptable, or need no action. An empty list is the normal result.',
  'Reviewer precedent: reviewer_feedback lists earlier decisions by the i18n lead for this language. "rejected" means she deleted the finding as not a real defect (reason given); "approved" means she kept it. Follow that precedent: drop candidates that match the pattern of a rejected item and keep those that match approved ones.',
  'General precedents from review (all languages): a button, link or CTA that rephrases the English but keeps its function (e.g. "View details" rendered as "More information" or "See the information") is NOT a glossary defect. A glossary term that is part of a fixed phrase (login credentials, customer support team, bank statement) does not have to use the standalone approved target. An established near-synonym (e.g. localización/ubicación) is not a defect unless glossary_note forbids it. A title or subject reworded to fit the message is not a term defect.',
  'Never judge accuracy against the English source, spelling, placeholders or HTML — they are out of scope.',
  'Severity: High = users see something clearly wrong (brand translated, forbidden term, formality rule broken in a prominent string). Medium = wrong approved term or style rule broken in a normal string. Low = stylistic drift or rarely seen string. At most a third of kept items may be High.',
  'Write "issue" in English, one sentence, quoting the rule or approved term, e.g. "Guide: \'use du, not Sie\' — string uses Ihr". Write "suggestion" as the corrected fragment in ' + job.lang_name + ' (not the whole string).',
  'Return ONLY JSON: {"decisions":[{"id":"c1","keep":true,"certainty":"high","severity":"Medium","issue":"...","suggestion":"..."}],"sample_findings":[{"sid":"s1","rule":"short rule name","severity":"Low","issue":"...","suggestion":"..."}],"glossary_conflicts":["..."]}. Include a decision for EVERY candidate id.'
].join(NL);

const payload = { language: job.lang_name, iso: iso, product: job.project_name, reviewer_feedback: job.feedback || [], candidates: candPayload, sample: sample };
const openaiBody = { model: 'gpt-4.1', temperature: 0, response_format: { type: 'json_object' }, messages: [{ role: 'system', content: SYS }, { role: 'user', content: JSON.stringify(payload) }] };

return [{ json: {
  iso: iso, lang_name: job.lang_name, project_name: job.project_name,
  keys_seen: keys.length, archived_skipped: archived, strings_checked: rows.length,
  candidates_total: cands.length, sent: send.length, overflow: overflow, systemic: systemic,
  sent_candidates: send.map(function (c) { return { id: c.id, type: c.type, sub: c.sub, rule: c.rule, sev: c.sev, key: c.key, d: (META[c.key] || {}).d || '', en: c.en, target: c.target, expected: c.expected, note: c.note }; }),
  sample: sample,
  has_work: rows.length > 0,
  errors: errors,
  openai_body: JSON.stringify(openaiBody)
} }];

const prep = $('Run checks').first().json;
const resp = $input.first().json || {};
let parsed = null;
let triageError = '';
try {
  const txt = resp.choices[0].message.content;
  parsed = JSON.parse(String(txt).replace(/^```json|```$/g, '').trim());
} catch (e) {
  triageError = 'LLM triage failed: ' + (resp.error ? JSON.stringify(resp.error).slice(0, 200) : String(e.message || e));
}
const SEV = { High: 1, Medium: 1, Low: 1 };
function sev(s, d) { return SEV[s] ? s : d; }
const byId = {};
for (const c of prep.sent_candidates) { byId[c.id] = c; }
const bySid = {};
for (const s of prep.sample) { bySid[s.sid] = s; }
const findings = [];
const keptRules = {};
if (parsed && Array.isArray(parsed.decisions)) {
  for (const d of parsed.decisions) {
    const c = byId[d.id];
    if (!c || d.keep !== true || String(d.certainty || 'high').toLowerCase() === 'low') { continue; }
    keptRules[c.type + ':' + c.rule] = c;
    findings.push({ check: c.type === 'glossary' ? 'Glossary' : 'Style', severity: sev(d.severity, c.sev), rule: c.type === 'glossary' ? (c.sub + ': ' + c.rule) : c.rule, key: c.key, key_description: c.d || '', en: c.en, translation: c.target, issue: String(d.issue || c.note || ''), suggestion: String(d.suggestion || c.expected || ''), found_by: 'automatic check + LLM triage' });
  }
} else {
  for (const c of prep.sent_candidates) {
    if (c.sub !== 'brand_not_preserved' && c.sub !== 'forbidden_used') { continue; }
    findings.push({ check: 'Glossary', severity: 'High', rule: c.sub + ': ' + c.rule, key: c.key, key_description: c.d || '', en: c.en, translation: c.target, issue: c.sub === 'brand_not_preserved' ? ('Brand name "' + c.rule + '" is not kept verbatim.') : ('Forbidden term "' + c.rule + '" used.'), suggestion: c.expected, found_by: 'automatic check (triage unavailable)' });
  }
}
if (parsed && Array.isArray(parsed.sample_findings)) {
  for (const f of parsed.sample_findings) {
    const s = bySid[f.sid];
    if (!s) { continue; }
    if (/\bno (issue|action|change|problem)|acceptable|appropriate|correctly|is fine|no breach|not a breach|remains clear/i.test(String(f.issue || ''))) { continue; }
    findings.push({ check: 'Style', severity: sev(f.severity, 'Low'), rule: 'sample: ' + String(f.rule || 'style guide'), key: s.key, key_description: s.key_description || '', en: s.en, translation: s.target, issue: String(f.issue || ''), suggestion: String(f.suggestion || ''), found_by: 'LLM style-guide sample' });
  }
}
for (const hk in prep.systemic) {
  const c = keptRules[hk];
  if (!c) { continue; }
  findings.push({ check: c.type === 'glossary' ? 'Glossary' : 'Style', severity: c.sev, rule: c.type === 'glossary' ? (c.sub + ': ' + c.rule) : c.rule, key: '(multiple)', en: '', translation: '', issue: 'Systemic: the check fired on ' + prep.systemic[hk] + ' strings; only the first ' + (c.type === 'style' ? 25 : 5) + ' were reviewed. Likely one consistent choice — fix with a sweep, not key by key.', suggestion: c.expected || '', found_by: 'automatic check' });
}
// ---------- reviewer precedent (deterministic) ----------
const fb = ($('When called by parent').first().json.feedback) || [];
function ruleLabel(c) { return c.type === 'glossary' ? (c.sub + ': ' + c.rule) : c.rule; }
function tkey(rule, t) { return String(rule) + '|' + String(t || '').slice(0, 150); }
const APP = {}, REJ = {}, APP_RULE = {}, REJ_RULE = {};
for (const x of fb) {
  if (x.decision === 'approved') { APP[tkey(x.rule, x.translation)] = true; APP_RULE[x.rule] = true; }
  if (x.decision === 'rejected') { REJ[tkey(x.rule, x.translation)] = true; REJ_RULE[x.rule] = true; }
}
const keptIds = {};
if (parsed && Array.isArray(parsed.decisions)) {
  for (const d of parsed.decisions) { if (d.keep === true && String(d.certainty || 'high').toLowerCase() !== 'low') { keptIds[d.id] = true; } }
}
for (let i = findings.length - 1; i >= 0; i--) {
  const f = findings[i];
  if (f.found_by.indexOf('LLM triage') !== -1 && REJ[tkey(f.rule, f.translation)]) { findings.splice(i, 1); }
}
if (parsed && Array.isArray(parsed.decisions)) {
  for (const c of prep.sent_candidates) {
    if (keptIds[c.id]) { continue; }
    const rl = ruleLabel(c);
    const exact = APP[tkey(rl, c.target)];
    const ruleLevel = c.type === 'style' && APP_RULE[rl] && !REJ_RULE[rl];
    if (!exact && !ruleLevel) { continue; }
    findings.push({ check: c.type === 'glossary' ? 'Glossary' : 'Style', severity: c.sev === 'High' ? 'Medium' : c.sev, rule: rl, key: c.key, key_description: c.d || '', en: c.en, translation: c.target, issue: (c.type === 'style' ? 'Guide: ' + c.note : 'Glossary: approved term \u201c' + c.expected + '\u201d not used.'), suggestion: c.expected || '', found_by: exact ? 'reviewer precedent (approved earlier)' : 'automatic check + reviewer precedent' });
  }
}
const seenF = {};
const deduped = [];
for (const f of findings) {
  const fk = f.key + '|' + String(f.issue || '').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
  if (seenF[fk]) { continue; }
  seenF[fk] = true;
  deduped.push(f);
}
findings.length = 0;
for (const f of deduped) { findings.push(f); }
const order = { High: 0, Medium: 1, Low: 2 };
findings.sort(function (a, b) { return (a.check < b.check ? -1 : a.check > b.check ? 1 : 0) || order[a.severity] - order[b.severity]; });
const errors = prep.errors.slice();
if (triageError) { errors.push(triageError); }
return [{ json: {
  iso: prep.iso, lang_name: prep.lang_name, strings_checked: prep.strings_checked, keys_seen: prep.keys_seen,
  candidates_total: prep.candidates_total, overflow: prep.overflow, triage_ok: !triageError,
  glossary_conflicts: parsed && Array.isArray(parsed.glossary_conflicts) ? parsed.glossary_conflicts.slice(0, 10) : [],
  findings: findings, errors: errors
} }];

const NL = String.fromCharCode(10);
const job = $('When called by parent').first().json;
const iso = job.iso;
const pages = $input.all();
const errors = [];
let keys = [];
for (const p of pages) {
  const j = p.json || {};
  const body = j.body !== undefined ? j.body : j;
  if (body && Array.isArray(body.keys)) { keys = keys.concat(body.keys); }
  else { errors.push('Lokalise page without keys array: ' + JSON.stringify(body).slice(0, 200)); }
}

const UB = '(?:(?<![\\p{L}\\p{N}_])(?=[\\p{L}\\p{N}_])|(?<=[\\p{L}\\p{N}_])(?![\\p{L}\\p{N}_]))';
function rx(src, flags) { return new RegExp(String(src).split('\\b').join(UB), 'u' + (flags || '')); }
const MARKUP = /\[%[^\]]*\]|%\d*\$?[sdfx@]|\{\{[^}]*\}\}|%\{[^}]*\}|\{[^}\s]*\}|<[^>]+>|&[a-zA-Z#0-9]+;|https?:\/\/\S+|[\w.+-]+@[\w-]+\.[\w.]+|\\[nrt]/g;
function strip(s) { return String(s || '').replace(MARKUP, ' '); }
function pickText(tr) {
  if (tr === null || tr === undefined) { return ''; }
  if (typeof tr === 'object') { return Object.values(tr).filter(function (v) { return v; }).join(' ¦ '); }
  const s = String(tr);
  if (s.charAt(0) === '{' && s.indexOf('"') !== -1) {
    try { const o = JSON.parse(s); if (o && typeof o === 'object') { return Object.values(o).filter(function (v) { return v; }).join(' ¦ '); } } catch (e) { }
  }
  return s;
}

const rows = [];
const META = {};
let archived = 0;
for (const k of keys) {
  if (k.is_archived) { archived++; continue; }
  const kn = k.key_name || {};
  const name = typeof kn === 'string' ? kn : (kn.web || kn.other || kn.ios || kn.android || String(k.key_id));
  let en = '';
  let tgt = '';
  for (const t of (k.translations || [])) {
    if (t.language_iso === 'en') { en = pickText(t.translation); }
    if (t.language_iso === iso) { tgt = pickText(t.translation); }
  }
  if (!en.trim() || !tgt.trim()) { continue; }
  const tags = Array.isArray(k.tags) ? k.tags.map(String) : [];
  META[name] = { d: String(k.description || k.context || '').trim().slice(0, 300), tags: tags.slice(0, 8) };
  rows.push({ k: name, en: en, t: tgt });
}

// ---------- glossary ----------
const WORD = /[\p{L}\p{M}]+(?:['’\-][\p{L}\p{M}]+)*/gu;
function norm(s) { return String(s).normalize('NFC').replace(/[\u00A0\u202F\u2009]/g, ' ').toLowerCase(); }
function words(s) { return (String(s).match(WORD) || []).map(norm); }
function variants(target) {
  const out = [];
